// =====================================================
// GLOBAL DATE SORT — OLDEST FIRST / ASCENDING
// Supports YYYY-MM-DD and DD-MM-YYYY
// =====================================================

function sortTransactionsOldestFirst(transactions) {

    function getSortableDate(value) {

        if (!value) return "";

        const dateString = String(value).trim();

        // YYYY-MM-DD
        let match = dateString.match(
            /^(\d{4})-(\d{1,2})-(\d{1,2})/
        );

        if (match) {
            return (
                match[1] + "-" +
                match[2].padStart(2, "0") + "-" +
                match[3].padStart(2, "0")
            );
        }

        // DD-MM-YYYY or DD/MM/YYYY
        match = dateString.match(
            /^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/
        );

        if (match) {
            return (
                match[3] + "-" +
                match[2].padStart(2, "0") + "-" +
                match[1].padStart(2, "0")
            );
        }

        // Unknown date format: keep it after valid dates
        return "";
    }

    return transactions.sort(function (a, b) {

        const dateA = getSortableDate(a.date);
        const dateB = getSortableDate(b.date);

        if (!dateA && !dateB) return 0;
        if (!dateA) return 1;
        if (!dateB) return -1;

        return dateA.localeCompare(dateB);
    });
}

// =====================================================
// GLOBAL DATE DISPLAY FORMAT — DD-MM-YYYY
// =====================================================

function formatDateDisplay(value) {

    if (!value) return "";

    const dateString = String(value).trim();

    // YYYY-MM-DD
    let match = dateString.match(
        /^(\d{4})-(\d{1,2})-(\d{1,2})$/
    );

    if (match) {
        return (
            match[3].padStart(2, "0") + "-" +
            match[2].padStart(2, "0") + "-" +
            match[1]
        );
    }

    // DD-MM-YYYY or DD/MM/YYYY
    match = dateString.match(
        /^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/
    );

    if (match) {
        return (
            match[1].padStart(2, "0") + "-" +
            match[2].padStart(2, "0") + "-" +
            match[3]
        );
    }

    // Leave unknown formats unchanged
    return dateString;
}

